#!/usr/bin/env bash
# Benchmark of a solver file: retired instructions on RV32_ISS for the 14 hardest distance-11 states (bench_states.txt,
# columns: state, optimal length, children generated by the C search), and the size of the solver's code.
#   ./bench.sh                    benchmark solver.s
#   ./bench.sh versions/solver_v1_direct.s
# retired includes about 5,000 instructions of harness (parse, replay, validate) in every run.
cd "$(dirname "$0")"
S=${1:-solver.s}
RIPES_BIN=${RIPES_BIN:-../../Ripes/build/Ripes.app/Contents/MacOS/Ripes}; RVCC=${RVCC:-riscv64-elf-gcc}
[ -f tables.s ] || make -s tables.s >/dev/null
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
sum=0; nodes=0; worst=0; fail=0
while read -r state len n; do
    $RVCC -E -P -x assembler-with-cpp -DUSE_TABLES=1 -DRENDER=0 -DSOLVER_FILE="\"$S\"" -DTEST_STATE="\"$state\"" -DTEST_LEN=$len main.s > "$T/t.s" || exit 2
    out=$("$RIPES_BIN" --mode cli --src "$T/t.s" -t asm --proc RV32_ISS --iret --timeout 120000 2>&1)
    code=$(echo "$out" | awk '/exited with code/{print $NF}'); ret=$(echo "$out" | awk '/instructions retired/{getline; print $1}')
    [ "$code" = 0 ] || fail=$((fail+1))
    sum=$((sum+ret)); nodes=$((nodes+n)); [ "$ret" -gt "$worst" ] && worst=$ret
    [ -z "$first" ] && first=$ret
done < bench_states.txt
# code size: link the flat file with GNU tools; solver text = total .text minus the .text of the harness with an empty solver
size_of() { $RVCC -E -P -x assembler-with-cpp -DUSE_TABLES=1 -DRENDER=0 -DSOLVER_FILE="\"$1\"" main.s > "$T/s.s" && \
            $RVCC -march=rv32i -mabi=ilp32 -nostdlib -static -T ../rv/link.ld -Wl,-e,main -o "$T/s.elf" "$T/s.s" 2>/dev/null && \
            riscv64-elf-size -A "$T/s.elf" | awk '/^\.text/{print $2}'; }
printf 'solver          %s\n' "$S"
printf 'hardest state   %d retired (41625372313211, 45,312 children)\n' "$first"
printf '14 hardest      %d retired, %.1f per child (harness included)\n' "$sum" "$(echo "$sum $nodes" | awk '{print $1/$2}')"
printf '    .text\n    .globl solve\nsolve:\n    ret\n' > "$T/empty.s"
TT=$(size_of "$S"); HH=$(size_of "$T/empty.s")
printf '.text           %s bytes in total, harness alone %s, so the solver is %s bytes\n' "$TT" "$HH" "$((TT - HH))"
printf 'failures        %d of 14\n' "$fail"
